package dev.DraGonFiirE.littleperformanceimprovements.client.render;
import java.util.*;import com.mojang.blaze3d.vertex.MeshData;import com.mojang.blaze3d.systems.RenderSystem;import net.minecraft.world.item.ItemStack;import team.creative.littletiles.client.render.overlay.PreviewRenderer;import team.creative.littletiles.LittleTiles;import team.creative.creativecore.common.util.type.Color;import dev.DraGonFiirE.littleperformanceimprovements.access.PreviewRenderingConfig;import dev.DraGonFiirE.littleperformanceimprovements.config.PreviewRendererMode;
public final class PyramidTextureSurfaceStyle {
 private static final Set<MeshData> meshes=Collections.newSetFromMap(new WeakHashMap<>());
 public static synchronized PreviewRenderer.BoxRenderResult mark(PreviewRenderer.BoxRenderResult result,ItemStack stack){if(result!=null&&result.data()!=null&&ChiselOnlyPreviewMode.current(stack)==PreviewRendererMode.Texture){var mesh=result.data();if(meshes.add(mesh)){var vertices=mesh.vertexBuffer();int stride=mesh.drawState().format().getVertexSize();if(mesh.drawState().format()==com.mojang.blaze3d.vertex.DefaultVertexFormat.POSITION_COLOR)for(int i=0;i<mesh.drawState().vertexCount();i++)vertices.put(i*stride+15,(byte)128);}}return result;}
 public static synchronized boolean contains(MeshData mesh){return meshes.contains(mesh);}
 public static Runnable wrap(MeshData mesh,Runnable setup){synchronized(PyramidTextureSurfaceStyle.class){if(!meshes.contains(mesh))return setup;}return ()->{if(setup!=null)setup.run();var config=(PreviewRenderingConfig)(Object)LittleTiles.CONFIG.rendering;Color color=config.littleperformanceimprovements$getPreviewColor();if(color==null)color=Color.WHITE;float alpha=1.0f;RenderSystem.setShaderColor(color.getRedDecimal(),color.getGreenDecimal(),color.getBlueDecimal(),alpha);RenderSystem.depthMask(false);};}
}
